#!name=🍟 Apple News 解锁.official
#!author=queitstart pro
#!date=2026-11-21
#!desc=Surge 模块
#!name =  iRingo: 📰 News
#!arguments=Proxy:🇺🇸美国,CountryCode:"US",NewsPlusUser:true
#!arguments-desc=Proxy: News 分流规则使用的策略名
CountryCode: 国家或地区代码
    ├ AUTO: 🇺🇳自动（跟随地区检测结果）
    ├ CN: 🇨🇳中国大陆
    ├ HK: 🇭🇰香港
    ├ TW: 🇹🇼台湾
    ├ SG: 🇸🇬新加坡
    ├ US: 🇺🇸美国
    ├ JP: 🇯🇵日本
    ├ AU: 🇦🇺澳大利亚
    ├ GB: 🇬🇧英国
    ├ KR: 🇰🇷韩国
    ├ CA: 🇨🇦加拿大
    └ IE: 🇮🇪爱尔兰
不同国家或地区提供的内容或有差别。

NewsPlusUser: [搜索]显示News+内容
是否显示News+搜索结果。

#!format=sgmodule

[Rule]
DOMAIN,gateway.icloud.com,{{{Proxy}}}
RULE-SET,https://github.com/NSRingo/News/releases/download/v3.1.5/News.list,{{{Proxy}}}

[MITM]
hostname = %APPEND% news-edge.apple.com, news-todayconfig-edge.apple.com, news-events.apple.com, news-sports-events.apple.com, news-client.apple.com, news-client-search.apple.com
